const $=id=>document.getElementById(id);
let items=[],uploads=[],originalBytes,originalName='',urls=[],worker=null,serial=0,busy=false;
const pending=new Map();
function status(text){$('status').textContent=text}
function objectURL(blob){const u=URL.createObjectURL(blob);urls.push(u);return u}
function cleanURLs(){urls.forEach(URL.revokeObjectURL);urls=[]}
function startWorker(){if(worker)return;worker=new Worker('match-worker.js');worker.onmessage=({data})=>{if(data.progress){status(`Verifying photo pairs: ${data.progress} / ${data.total}…`);return}const p=pending.get(data.request);if(p){pending.delete(data.request);data.error?p.reject(Error(data.error)):p.resolve(data)}};worker.onerror=()=>{for(const p of pending.values())p.reject(Error('The matching engine could not load. Refresh the page and try again.'));pending.clear();worker.terminate();worker=null}}
function call(type,data={},transfer=[]){startWorker();return new Promise((resolve,reject)=>{const request=++serial;pending.set(request,{resolve,reject});worker.postMessage({request,type,...data},transfer)})}
function toBlob(canvas,type='image/png',quality){return new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('Image conversion failed')),type,quality))}
async function decode(bytes,name,mark=false,isUpload=false){
 const blob=new Blob([bytes]),im=await createImageBitmap(blob);const id='image-'+(++serial);
 try{
  // Preserve aspect ratio for local features. Stretching to a square breaks geometry.
  const scale=Math.min(1,800/Math.max(im.width,im.height));const sample=document.createElement('canvas');sample.width=Math.max(1,Math.round(im.width*scale));sample.height=Math.max(1,Math.round(im.height*scale));const ctx=sample.getContext('2d',{willReadFrequently:true});ctx.fillStyle='white';ctx.fillRect(0,0,sample.width,sample.height);ctx.drawImage(im,0,0,sample.width,sample.height);const rgba=ctx.getImageData(0,0,sample.width,sample.height).data;await call('extract',{id,width:sample.width,height:sample.height,rgba:rgba.buffer},[rgba.buffer]);
  let png;if(isUpload){const canvas=document.createElement('canvas'),ratio=Math.min(1,2200/Math.max(im.width,im.height));canvas.width=Math.round(im.width*ratio);canvas.height=Math.round(im.height*ratio);const c=canvas.getContext('2d');c.drawImage(im,0,0,canvas.width,canvas.height);if(mark){const h=Math.max(24,Math.round(canvas.height*.035));c.fillStyle='rgba(23,55,40,.8)';c.fillRect(0,canvas.height-h,canvas.width,h);c.fillStyle='white';c.font=`bold ${Math.round(h*.6)}px sans-serif`;c.fillText('TEST REPLACEMENT',15,canvas.height-h*.22);ctx.drawImage(canvas,0,0,sample.width,sample.height)}png=await (await toBlob(canvas)).arrayBuffer();canvas.width=canvas.height=1}
  const preview=objectURL(await toBlob(sample,'image/jpeg',.85));return {id,preview,png,name};
 }finally{im.close()}
}
function invalidate(){if(busy)return;$('results').hidden=true;items=[];uploads=[];originalBytes=null;status('Files changed. Scan again to compare the new selection.')}
$('doc').onchange=()=>{$('docLabel').textContent=$('doc').files[0]?.name||'Choose a DOCX';invalidate()};
$('photos').onchange=()=>{$('photoLabel').textContent=$('photos').files.length+' photos selected';invalidate()};
$('watermark').onchange=invalidate;$('extra').onchange=invalidate;
const descriptions={strict:'Strong, widely spread matching details. Best when you want fewer automatic replacements.',balanced:'Recommended. Balances reliable matches with crops and lighting changes.',flexible:'Accepts less overlap. Check the suggested matches before export.',lenient:'Accepts the least overlap. Ambiguous and weak results still require review.'};
function updateModeHelp(){$('modeHelp').textContent=descriptions[$('tolerance').value]}
function applyMode(){items.forEach(p=>{if(!p.manual)Object.assign(p,RobustMatcher.decide(p.ranks,$('tolerance').value))});render();updateModeHelp()}
$('tolerance').onchange=()=>{updateModeHelp();if(items.length){applyMode();status('Matching level updated. Your manual choices were kept.')}};updateModeHelp();
function tally(){const counts={matched:0,missing:0,review:0},used=new Set();items.forEach(p=>{counts[p.status]++;if(p.index!==null)used.add(p.index)});$('summary').textContent=`${counts.matched} matched · ${counts.missing} missing · ${counts.review} to review`;$('download').disabled=busy||counts.review>0;$('download').title=counts.review?'Resolve all review items first.':'';$('ignoredSummary').textContent=`${uploads.length-used.size} unused uploads`;$('ignored').replaceChildren();uploads.forEach((u,i)=>{if(!used.has(i)){const img=document.createElement('img');img.src=u.preview;img.alt=u.name;img.title=u.name;$('ignored').append(img)}})}
function evidence(r){return r.inliers?`${r.inliers} aligned details · ${Math.round(r.coverage*100)}% spatial coverage`:'No verified shared details'}
function render(){const cards=$('cards');cards.replaceChildren();items.forEach((p,i)=>{
 const card=document.createElement('article');card.className='card';const heading=document.createElement('h3');heading.textContent=`Photo ${i+1}${p.part!=='word/document.xml'?' · '+p.part.split('/').pop():''}`;const badge=document.createElement('div');badge.className='badge '+p.status;badge.textContent=p.status==='matched'?(p.manual?'MANUALLY SELECTED':'MATCHED'):p.status==='missing'?'NOT FOUND':'REVIEW REQUIRED';
 const pair=document.createElement('div');pair.className='pair';const left=document.createElement('div'),right=document.createElement('div');const la=document.createElement('label'),lb=document.createElement('label');la.textContent='IN THE DOCUMENT';lb.textContent='REPLACEMENT';const a=document.createElement('img'),b=document.createElement('img');a.src=p.preview;a.alt='Original document photo '+(i+1);a.onclick=()=>openImage(p.preview,a.alt);a.title='Click to enlarge';b.alt='Selected replacement';if(p.index!==null){b.src=uploads[p.index].preview;b.onclick=()=>openImage(uploads[p.index].preview,uploads[p.index].name)}else b.style.visibility='hidden';left.append(la,a);right.append(lb,b);pair.append(left,right);
 const reason=document.createElement('p');reason.className='matchReason';reason.textContent=p.reason;
 const sel=document.createElement('select');sel.setAttribute('aria-label','Replacement for photo '+(i+1));sel.add(new Option('Review required — choose a photo','review'));sel.add(new Option('Not found — replace with text','missing'));p.ranks.forEach(r=>sel.add(new Option(`${uploads[r.index].name} — ${r.inliers} aligned details`,String(r.index))));sel.value=p.index===null?p.status:String(p.index);
 function choose(value){p.manual=true;if(value==='review'||value==='missing'){p.status=value;p.index=null;p.reason=value==='missing'?'Manually marked not found.':'Please choose a replacement or mark not found.'}else{p.status='matched';p.index=Number(value);p.reason='Manually selected: '+uploads[p.index].name}render()}
 sel.onchange=()=>choose(sel.value);card.append(heading,badge,pair,reason,sel);
 if(p.status==='review'){const candidates=document.createElement('div');candidates.className='candidates';p.ranks.slice(0,3).forEach(r=>{const button=document.createElement('button');button.type='button';button.className='candidate';const img=document.createElement('img');img.src=uploads[r.index].preview;img.alt=uploads[r.index].name;const text=document.createElement('span');text.textContent=evidence(r);button.title='Select '+uploads[r.index].name;button.append(img,text);button.onclick=()=>choose(String(r.index));candidates.append(button)});card.append(candidates)}
 if(p.manual){const reset=document.createElement('button');reset.type='button';reset.className='reset';reset.textContent='Use automatic suggestion';reset.onclick=()=>{p.manual=false;applyMode()};card.append(reset)}cards.append(card)});tally()}
function openImage(src,title){$('largeImage').src=src;$('imageTitle').textContent=title;$('imageDialog').showModal()}
$('closeImage').onclick=()=>$('imageDialog').close();
function setBusy(value){busy=value;for(const id of ['scan','doc','photos','watermark','extra','tolerance'])$(id).disabled=value;$('cancel').hidden=!value}
$('cancel').onclick=()=>{if(worker){worker.terminate();worker=null}for(const p of pending.values())p.reject(Error('Scan cancelled.'));pending.clear()};
$('scan').onclick=async()=>{
 if(!$('doc').files.length||!$('photos').files.length){status('Choose a DOCX and at least one photo.');return}
 setBusy(true);$('results').hidden=true;cleanURLs();items=[];uploads=[];
 try{status('Loading local matching engine…');await call('ready');await call('clear');originalName=$('doc').files[0].name;originalBytes=await $('doc').files[0].arrayBuffer();const zip=await JSZip.loadAsync(originalBytes);if(!zip.file('word/document.xml'))throw Error('This file is not a valid Word DOCX.');const mediaCache=new Map();let readCount=0;items=await PhotoMatch.scan(zip,async(bytes,name)=>{if(!mediaCache.has(name)){status(`Reading document photo ${++readCount}…`);mediaCache.set(name,await decode(bytes,name))}return mediaCache.get(name)},$('extra').checked);if(!items.length)throw Error('No supported embedded photos found.');for(const f of $('photos').files){status(`Reading upload ${uploads.length+1} of ${$('photos').files.length}…`);uploads.push(await decode(await f.arrayBuffer(),f.name,$('watermark').checked,true))}status('Checking which details align in each photo pair…');const {ranks}=await call('rank',{docs:items.map(p=>p.id),uploads:uploads.map(p=>p.id)});items.forEach((p,i)=>{p.ranks=ranks[i];p.manual=false;Object.assign(p,RobustMatcher.decide(p.ranks,$('tolerance').value))});await call('clear');setBusy(false);render();$('results').hidden=false;status('Scan complete. Review the matches, especially photos marked for review.');$('results').scrollIntoView({behavior:'smooth',block:'start'})}
 catch(e){status(e.message==='Scan cancelled.'?e.message:'Error: '+e.message)}finally{setBusy(false)}
};
$('download').onclick=async()=>{if(busy||!originalBytes)return;setBusy(true);$('download').disabled=true;try{status('Building your updated document…');const zip=await JSZip.loadAsync(originalBytes);const out=await PhotoMatch.exportDoc(zip,items,uploads);const a=document.createElement('a');a.href=objectURL(new Blob([out],{type:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'}));a.download=originalName.replace(/\.docx$/i,'')+'-updated.docx';a.click();status('Updated DOCX downloaded.')}catch(e){status('Error: '+e.message)}finally{setBusy(false);tally()}};
